import { identityFromJson } from '@/domain/LocalizedIdentity';
import { SubjectId } from '@/domain/SubjectId';
import { PageIdentifiers } from '@/domain/PageIdentifiers';
import { StatementList } from '@/domain/StatementList';
import { StatementDeserializer } from '@/persistence/StatementDeserializer';
import { Subject } from '@/domain/Subject';
import { schemaReferenceName } from '@/domain/SchemaReference';
import { hostSubjectFromJson } from '@/persistence/hostSubjectFromJson';

export class SubjectDeserializer {

	public constructor(
		private readonly statementDeserializer: StatementDeserializer,
	) {
	}

	public deserialize( json: any ): Subject {
		const id = new SubjectId( json.id );
		const label = json.label ?? null;
		const displayName = json.displayName;
		const displayNameIsGenerated = json.displayNameIsGenerated;
		// Interim: the frontend still carries a bare Schema name, so a reference from another Source
		// collapses to its name here. It survives until sourced Subjects render, which is what needs
		// the Source to resolve the Schema through.
		const schema = schemaReferenceName( json.schema );

		const pageIdentifiers = new PageIdentifiers( json.pageId, json.pageTitle );
		const parsed = this.deserializeStatements( json.statements );
		const statementList = new StatementList( [ ...parsed ], json.fieldNotes || {} );

		return new Subject(
			id,
			label,
			displayName,
			displayNameIsGenerated,
			schema,
			statementList,
			pageIdentifiers,
			hostSubjectFromJson( json.hostSubject ),
			identityFromJson( json ), json.schema,
		);
	}

	public deserializeStatements( json: any ): StatementList {
		return new StatementList(
			Object.entries( json )
				.map( ( [ key, statementJson ] ) => this.statementDeserializer.deserialize(
					key,
					statementJson,
				) ),
		);
	}

}
